insert into public.words (id, word, romanization, category, secondary_category, short_desc, short_desc_i18n, pronunciation, meanings, origin, origin_i18n, usage, usage_i18n, related_words, aliases, likes, saves, translations) values
('565', '롬곡', 'Rom-gok', 'outdated-slang', 'yaminjeongeum', '''눈물''을 거꾸로 돌려 적은 야민정음', '{"de": "''Tränen'' auf dem Kopf geschrieben — ein rotiertes Yaminjeongeum-Wort", "en": "''Tears'' written upside down — a rotated Yaminjeongeum word", "es": "''Lágrimas'' escrito al revés: un Yaminjeongeum rotado", "ja": "「涙」を180度回して書いた野民正音", "vi": "''Nước mắt'' viết lộn ngược — một từ Yaminjeongeum quay"}'::jsonb, '[롬곡]', '[{"type": "명사", "examples": [{"de": "Bei der Szene sind mir Rom-gok gekommen.", "es": "Esa escena me hizo soltar rom-gok.", "ja": "このシーン見てロムゴク流した", "vi": "Xem cảnh đó là tuôn rom-gok luôn.", "eng": "That scene had me shedding rom-gok.", "kor": "이 장면 보고 롬곡 흘렸어"}, {"de": "Ich brauchte drei Sekunden, um zu sehen, dass 롬곡옾눞 폭풍눈물 ist.", "es": "Tardé tres segundos en ver que 롬곡옾눞 es 폭풍눈물.", "ja": "롬곡옾눞が폭풍눈물だと気づくのに3秒かかった", "vi": "Mất ba giây mới nhận ra 롬곡옾눞 là 폭풍눈물.", "eng": "It took me three seconds to realise 롬곡옾눞 is 폭풍눈물.", "kor": "롬곡옾눞이 폭풍눈물인 거 알아채는 데 3초 걸렸다"}], "definition": "''눈물''을 종이째 180도 돌린 모양으로 적은 말. 글자를 닮은 모양으로 바꿔 쓰는 놀이 ''야민정음'' 중에서도 회전 방식의 대표 예다. 길게 쓴 ''롬곡옾눞''은 ''폭풍눈물''을 돌린 것으로, 눈물이 쏟아질 만큼 슬플 때뿐 아니라 너무 웃길 때도 썼다. 2017~2018년에 크게 유행했고 지금은 거의 쓰지 않는다.", "definition_i18n": {"de": "''눈물'' (Tränen), geschrieben als hätte man die Seite um 180 Grad gedreht. Es ist das Paradebeispiel für den Rotationstyp des Yaminjeongeum, des Spiels, Hangul mit ähnlich aussehenden Formen umzuschreiben. Das längere 롬곡옾눞 dreht 폭풍눈물, einen Tränensturm — für Herzzerreißendes wie für zu Komisches. Groß 2017-2018, heute fast tot.", "en": "''눈물'' (tears) written as if the page were turned 180 degrees. It is the flagship rotation-type example of Yaminjeongeum, the game of respelling Hangul with look-alike shapes. The longer 롬곡옾눞 rotates 폭풍눈물, a storm of tears — used both for genuinely crushing moments and for things too funny to bear. Big in 2017-2018, now nearly dead.", "es": "''눈물'' (lágrimas) escrito como si girases la página 180 grados. Es el ejemplo estrella del tipo rotación en Yaminjeongeum, el juego de reescribir hangul con formas parecidas. El más largo 롬곡옾눞 gira 폭풍눈물, tormenta de lágrimas, y servía tanto para lo devastador como para lo demasiado gracioso. Arrasó en 2017-2018 y hoy casi no se usa.", "ja": "「눈물(涙)」を紙ごと180度回した形で書いた語。字を似た形に置き換える遊び「野民正音」の回転型の代表例。長い「롬곡옾눞」は「폭풍눈물(涙の嵐)」を回したもので、泣けるほど悲しいときだけでなく笑いすぎるときにも使った。2017〜18年に大流行し、今はほぼ使われない。", "vi": "''눈물'' (nước mắt) viết như thể quay tờ giấy 180 độ. Đây là ví dụ tiêu biểu cho kiểu quay trong Yaminjeongeum, trò viết lại Hangul bằng những hình giống nhau. Dạng dài 롬곡옾눞 là quay của 폭풍눈물, bão nước mắt — dùng cả khi quá buồn và khi quá buồn cười. Rất thịnh 2017-2018, giờ gần như không dùng."}}]'::jsonb, '야민정음은 디시인사이드 국내야구 갤러리(''야갤'')에서 발전한 표기 놀이로, ''야갤''과 ''훈민정음''을 합쳐 붙은 이름이다. 모양이 닮은 자모로 바꾸기(멍멍이→댕댕이), 글자를 돌리기, 압축하기 등 여러 방식이 있고 롬곡은 그중 회전 방식에 해당한다. ''눈물''을 180도 돌리면 ''롬곡'', ''폭풍눈물''을 돌리면 ''롬곡옾눞''이 된다. 2017~2018년 언론이 신조어로 다룰 만큼 널리 퍼졌다.', '{"de": "Yaminjeongeum ist ein Umschreibspiel aus DCInsides Galerie für heimischen Baseball (''Yagal''); der Name mischt Yagal und Hunminjeongeum. Es tauscht ähnlich aussehende Buchstaben (멍멍이 zu 댕댕이), dreht Zeichen, staucht sie und mehr — 롬곡 ist die Drehvariante. Dreh 눈물 um 180 Grad und du hast 롬곡; dreh 폭풍눈물 und du hast 롬곡옾눞. Es verbreitete sich so weit, dass die Presse es 2017-2018 als neuen Slang behandelte.", "en": "Yaminjeongeum is a respelling game that grew out of DCInside''s domestic-baseball gallery (''Yagal''); the name blends Yagal with Hunminjeongeum. It works by swapping look-alike letters (멍멍이 to 댕댕이), rotating characters, compressing them and so on — 롬곡 is the rotation kind. Turn 눈물 180 degrees and you get 롬곡; turn 폭풍눈물 and you get 롬곡옾눞. It spread widely enough that the press covered it as new slang in 2017-2018.", "es": "El Yaminjeongeum es un juego de reescritura surgido de la galería de béisbol nacional de DCInside (''Yagal''); el nombre mezcla Yagal con Hunminjeongeum. Funciona cambiando letras parecidas (멍멍이 a 댕댕이), rotando caracteres, comprimiéndolos, etc. — 롬곡 es del tipo rotación. Gira 눈물 180 grados y sale 롬곡; gira 폭풍눈물 y sale 롬곡옾눞. Se extendió tanto que la prensa lo trató como jerga nueva en 2017-2018.", "ja": "野民正音はDCインサイド国内野球ギャラリー(「野ギャル」)で発展した表記遊びで、「野ギャル」と「訓民正音」を合わせた名。形の似た字母に替える(멍멍이→댕댕이)、字を回す、圧縮するなど方式があり、롬곡は回転型。「눈물」を180度回すと「롬곡」、「폭풍눈물」を回すと「롬곡옾눞」。2017〜18年には新語として報道されるほど広まった。", "vi": "Yaminjeongeum là trò viết lại phát triển từ gallery bóng chày nội địa của DCInside (''Yagal''); tên ghép Yagal với Hunminjeongeum. Cách làm là đổi chữ cái trông giống (멍멍이 thành 댕댕이), quay chữ, nén chữ... — 롬곡 thuộc kiểu quay. Quay 눈물 180 độ ra 롬곡; quay 폭풍눈물 ra 롬곡옾눞. Nó lan rộng đến mức báo chí đưa tin như từ mới vào 2017-2018."}'::jsonb, '2017~2018년에 몰려 쓰였고 지금은 야민정음 자체가 식어 거의 안 쓴다. 야민정음 중 ''댕댕이'', ''띵곡'', ''커엽다''는 살아남았지만 롬곡은 그러지 못한 쪽. 어느 쪽으로 검색해도 항목 하나다 — ''롬곡'', ''롬곡옾눞'', 그리고 마지막 글자를 잘못 적은 ''롬곡옾높''까지 모두 이 단어로 찾을 수 있다.', '{"de": "Es ballte sich 2017-2018 und wird kaum noch verwendet, seit die Yaminjeongeum-Mode abgekühlt ist. Von den gedrehten Wörtern überlebten 댕댕이, 띵곡 und 커엽다; 롬곡 nicht. Jede Form führt zu diesem einen Eintrag — 롬곡, 롬곡옾눞 und der häufige Tippfehler 롬곡옾높.", "en": "It clustered in 2017-2018 and is barely used now that the whole Yaminjeongeum fad has cooled. Among rotated words, 댕댕이, 띵곡 and 커엽다 survived; 롬곡 did not. Searching any form lands on this one entry — 롬곡, 롬곡옾눞, and the common misspelling 롬곡옾높 all find it.", "es": "Se concentró en 2017-2018 y hoy apenas se usa, ya enfriada la moda del Yaminjeongeum. De las palabras rotadas sobrevivieron 댕댕이, 띵곡 y 커엽다; 롬곡 no. Buscar cualquier forma lleva a esta única entrada: 롬곡, 롬곡옾눞 y la errata habitual 롬곡옾높.", "ja": "2017〜18年に集中して使われ、野民正音自体が冷めた今はほぼ使わない。回転語のうち「댕댕이」「띵곡」「커엽다」は生き残ったが롬곡は残らなかった。どの表記で検索しても項目は一つ — 「롬곡」「롬곡옾눞」、最後の字を誤った「롬곡옾높」でも見つかる。", "vi": "Nó tập trung ở 2017-2018 và giờ hầu như không dùng khi trào lưu Yaminjeongeum đã nguội. Trong các từ quay, 댕댕이, 띵곡 và 커엽다 sống sót; 롬곡 thì không. Tra dạng nào cũng ra một mục này — 롬곡, 롬곡옾눞, và cả lỗi viết phổ biến 롬곡옾높."}'::jsonb, array['댕댕이', '띵곡', '커엽다', '띵작']::text[], array['롬곡옾눞', '롬곡옾높']::text[], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Tears (written upside down)"}, {"lang": "🇯🇵 JA", "text": "涙(180度回した表記)"}, {"lang": "🇨🇳 ZH", "text": "眼泪(倒转写法)"}, {"lang": "🇻🇳 VI", "text": "Nước mắt (viết lộn ngược)"}, {"lang": "🇪🇸 ES", "text": "Lágrimas (escrito al revés)"}, {"lang": "🇩🇪 DE", "text": "Tränen (umgedreht geschrieben)"}]'::jsonb);

commit;
